-- rebuild the audit trail for the loaded history
INSERT INTO ticket_status_log (ticket_id, old_status, new_status, changed_at)
SELECT ticket_id, NULL, 'Open', created_at FROM tickets;
INSERT INTO ticket_status_log (ticket_id, old_status, new_status, changed_at)
SELECT ticket_id, 'Open', 'In Progress', created_at + interval '20 minutes' FROM tickets WHERE status IN ('In Progress', 'Resolved');
INSERT INTO ticket_status_log (ticket_id, old_status, new_status, changed_at)
SELECT ticket_id, 'In Progress', 'Resolved', resolved_at FROM tickets WHERE status = 'Resolved';

-- historic SLA alerts
INSERT INTO sla_alerts (ticket_id, alert_type, created_at)
SELECT ticket_id, 'Resolved Late', resolved_at FROM tickets WHERE status = 'Resolved' AND resolved_at > sla_deadline
ON CONFLICT DO NOTHING;
INSERT INTO sla_alerts (ticket_id, alert_type)
SELECT ticket_id, 'Active Exceeded' FROM tickets WHERE status <> 'Resolved' AND sla_deadline < now()
ON CONFLICT DO NOTHING;

ALTER TABLE tickets ENABLE TRIGGER USER;

SELECT setval(pg_get_serial_sequence('departments','dept_id'), (SELECT MAX(dept_id) FROM departments));
SELECT setval(pg_get_serial_sequence('users','user_id'), (SELECT MAX(user_id) FROM users));
SELECT setval(pg_get_serial_sequence('technicians','tech_id'), (SELECT MAX(tech_id) FROM technicians));
SELECT setval(pg_get_serial_sequence('tickets','ticket_id'), (SELECT MAX(ticket_id) FROM tickets));
COMMIT;
